// Claude AI chat — uses local `claude` CLI via stdin (no API key required)
const { spawn } = require('child_process');

app.post('/api/ai/chat', (req, res) => {
  res.setTimeout(0); // No timeout — allow complex long-running requests
  const { messages, system } = req.body;
  if (!Array.isArray(messages) || messages.length === 0) {
    return res.status(400).json({ error: 'messages array required' });
  }

  const systemText = system || 'You are an expert Claude Code assistant helping users write and improve their Claude agents, commands, rules, and CLAUDE.md files. Be concise and practical.';

  let prompt = systemText + '\n\n';
  for (const msg of messages) {
    if (msg.role === 'user') prompt += `Human: ${msg.content}\n\n`;
    else if (msg.role === 'assistant') prompt += `Assistant: ${msg.content}\n\n`;
  }
  prompt += 'Assistant:';

  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const childEnv = { ...process.env, HOME: os.homedir() };
  delete childEnv.CLAUDECODE;

  // Use stdin to avoid OS argument length limits; -p without an argument reads from stdin
  const proc = spawn(claudePath, ['-p'], {
    env: childEnv,
  });

  let output = '';
  let errOutput = '';

  proc.stdout.on('data', (data) => { output += data.toString(); });
  proc.stderr.on('data', (data) => { errOutput += data.toString(); });

  proc.on('close', (code) => {
    if (code !== 0) {
      return res.status(500).json({ error: errOutput.trim() || `claude exited with code ${code}` });
    }
    res.json({ content: output.trim() });
  });

  proc.on('error', (err) => {
    res.status(500).json({ error: `Failed to run claude: ${err.message}` });
  });

  // Write prompt via stdin and close
  proc.stdin.write(prompt, 'utf8');
  proc.stdin.end();
});

// Claude AI chat — streaming SSE variant
app.post('/api/ai/stream', (req, res) => {
  res.setTimeout(0);
  const { messages, system } = req.body;
  if (!Array.isArray(messages) || messages.length === 0) {
    return res.status(400).json({ error: 'messages array required' });
  }

  const systemText = system || 'You are an expert Claude Code assistant helping users write and improve their Claude agents, commands, rules, and CLAUDE.md files. Be concise and practical.';

  let prompt = systemText + '\n\n';
  for (const msg of messages) {
    if (msg.role === 'user') prompt += `Human: ${msg.content}\n\n`;
    else if (msg.role === 'assistant') prompt += `Assistant: ${msg.content}\n\n`;
  }
  prompt += 'Assistant:';

  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.flushHeaders();

  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const childEnv = { ...process.env, HOME: os.homedir() };
  delete childEnv.CLAUDECODE;

  const proc = spawn(claudePath, ['-p'], { env: childEnv });
  let fullOutput = '';

  proc.stdout.on('data', (data) => {
    const chunk = data.toString();
    fullOutput += chunk;
    res.write(`data: ${JSON.stringify({ type: 'chunk', content: chunk })}\n\n`);
  });

  proc.stderr.on('data', () => {});

  proc.on('close', (code) => {
    if (code !== 0) {
      res.write(`data: ${JSON.stringify({ type: 'error', error: 'Claude process failed' })}\n\n`);
    } else {
      res.write(`data: ${JSON.stringify({ type: 'done', content: fullOutput.trim() })}\n\n`);
    }
    res.end();
  });

  proc.on('error', (err) => {
    res.write(`data: ${JSON.stringify({ type: 'error', error: err.message })}\n\n`);
    res.end();
  });

  proc.stdin.write(prompt, 'utf8');
  proc.stdin.end();

  req.on('close', () => { try { proc.kill(); } catch {} });
});

// --- Agent Orchestration ---
function loadOrchestrations() {
  try {
    if (fs.existsSync(ORCHESTRATIONS_PATH)) return JSON.parse(fs.readFileSync(ORCHESTRATIONS_PATH, 'utf-8'));
  } catch {}
  return [];
}

function saveOrchestrations(list) {
  fs.writeFileSync(ORCHESTRATIONS_PATH, JSON.stringify(list, null, 2));
}

app.get('/api/orchestrations', (req, res) => {
  res.json(loadOrchestrations());
});

app.post('/api/orchestrations', (req, res) => {
  const { id, name, nodes, edges } = req.body;
  if (!name || !Array.isArray(nodes) || !Array.isArray(edges)) {
    return res.status(400).json({ error: 'name, nodes, edges required' });
  }
  const list = loadOrchestrations();
  const now = new Date().toISOString();
  const orcId = id || genId();
  const idx = list.findIndex(o => o.id === orcId);
  const orc = { id: orcId, name, nodes, edges, updatedAt: now, createdAt: now };
  if (idx >= 0) { orc.createdAt = list[idx].createdAt; list[idx] = orc; }
  else list.unshift(orc);
  saveOrchestrations(list);
  res.json({ id: orcId });
});

app.get('/api/orchestrations/:id', (req, res) => {
  const orc = loadOrchestrations().find(o => o.id === req.params.id);
  if (!orc) return res.status(404).json({ error: 'Not found' });
  res.json(orc);
});

app.delete('/api/orchestrations/:id', (req, res) => {
  saveOrchestrations(loadOrchestrations().filter(o => o.id !== req.params.id));
  res.json({ ok: true });
});

// Topological sort helper
function topoSort(nodes, edges) {
  const inDegree = {};
  const adj = {};
  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
  for (const e of edges) {
    adj[e.source].push(e.target);
    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
  }
  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
  const order = [];
  while (queue.length) {
    const id = queue.shift();
    order.push(id);
    for (const next of adj[id]) {
      inDegree[next]--;
      if (inDegree[next] === 0) queue.push(next);
    }
  }
  return order;
}

function runClaudeSync(prompt, timeoutMs = 120000) {
  return new Promise((resolve, reject) => {
    const claudePath = process.env.CLAUDE_PATH || 'claude';
    const childEnv = { ...process.env, HOME: os.homedir() };
    delete childEnv.CLAUDECODE;
    const proc = spawn(claudePath, ['-p'], { env: childEnv });
    let out = '', err = '';
    let killed = false;

    const timer = setTimeout(() => {
      killed = true;
      proc.kill('SIGTERM');
      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
    }, timeoutMs);

    proc.stdout.on('data', d => { out += d.toString(); });
    proc.stderr.on('data', d => { err += d.toString(); });
    proc.on('close', code => {
      clearTimeout(timer);
      if (killed) reject(new Error(`Node execution timed out after ${timeoutMs / 1000}s`));
      else if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
      else resolve(out.trim());
    });
    proc.on('error', (e) => { clearTimeout(timer); reject(e); });
    proc.stdin.write(prompt, 'utf8');
    proc.stdin.end();
  });
}

app.post('/api/orchestrations/run', async (req, res) => {
  res.setTimeout(0);
  const { nodes, edges, task } = req.body;
  if (!Array.isArray(nodes) || !task) return res.status(400).json({ error: 'nodes and task required' });

  const nodeMap = Object.fromEntries(nodes.map(n => [n.id, n]));
  const order = topoSort(nodes, edges || []);

  // Build agent content map from files
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const agentContentMap = {};

  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  for (const a of globalAgents) agentContentMap[a.name] = a.body || a.raw;

  for (const p of projects) {
    for (const a of p.agents) agentContentMap[a.name] = a.body || a.raw;
  }

  const results = {};
  let lastOutput = task;

  // SSE for streaming progress
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const send = (data) => res.write(`data: ${JSON.stringify(data)}\n\n`);

  try {
    for (const nodeId of order) {
      const node = nodeMap[nodeId];
      if (!node) continue;

      // Skip start/task-input nodes — store task as their output for downstream nodes
      if (node.data?.isStart) {
        results[nodeId] = task;
        send({ type: 'done', nodeId, label: node.data?.label || nodeId, output: task, skipped: true });
        continue;
      }

      const agentName = node.data?.agentName;
      const baseInstructions = agentName ? (agentContentMap[agentName] || '') : '';
      const nodeInstructions = node.data?.instructions || '';
      const nodeLabel = node.data?.label || agentName || nodeId;

      send({ type: 'start', nodeId, label: nodeLabel });

      // Build context from upstream node outputs
      const incomingEdges = (edges || []).filter(e => e.target === nodeId);
      let context = '';
      if (incomingEdges.length > 0) {
        context = incomingEdges.map(e => {
          const prevLabel = nodeMap[e.source]?.data?.label || e.source;
          return `## Output from ${prevLabel}:\n${results[e.source] || ''}`;
        }).join('\n\n');
      } else {
        context = `## Task:\n${task}`;
      }

      // Build prompt with clear structure: role → task → context → output directive
      let prompt = '';
      if (baseInstructions) {
        prompt += baseInstructions + '\n\n';
      }
      if (nodeInstructions) {
        prompt += `## Your Specific Task for This Step:\n${nodeInstructions}\n\n`;
      }
      prompt += `---\n\n${context}\n\n`;
      prompt += `---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary, evaluations, or descriptions of what you would do. Output only the finished work product itself.`;

      try {
        const output = await runClaudeSync(prompt);
        results[nodeId] = output;
        lastOutput = output;
        send({ type: 'done', nodeId, label: nodeLabel, output });
      } catch (err) {
        send({ type: 'error', nodeId, label: nodeLabel, error: err.message });
        break;
      }
    }
    send({ type: 'complete', finalOutput: lastOutput });
  } catch (err) {
    send({ type: 'error', nodeId: null, label: null, error: err.message });
  }

  res.end();
});

// Agent Playground — test any agent with a prompt (SSE streaming)
app.post('/api/playground/run', (req, res) => {
  const { agentName, prompt: userPrompt, customInstructions } = req.body;
  if (!userPrompt) return res.status(400).json({ error: 'Prompt is required' });

  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const send = (data) => res.write(`data: ${JSON.stringify(data)}\n\n`);

  (async () => {
    try {
      // Load agent instructions
      let instructions = '';
      if (agentName) {
        const agentContentMap = {};
        const globalAgentsDir = path.join(CLAUDE_DIR, 'agents');
        if (fs.existsSync(globalAgentsDir)) {
          for (const file of fs.readdirSync(globalAgentsDir).filter(f => f.endsWith('.md'))) {
            const content = fs.readFileSync(path.join(globalAgentsDir, file), 'utf-8');
            const nameMatch = content.match(/^name:\s*(.+)$/m);
            const key = nameMatch ? nameMatch[1].trim() : file.replace('.md', '');
            agentContentMap[key] = content;
            agentContentMap[file.replace('.md', '')] = content;
          }
        }
        instructions = agentContentMap[agentName] || '';
      }

      // Use custom instructions override if provided
      if (customInstructions) {
        instructions = customInstructions;
      }

      let fullPrompt = '';
      if (instructions) {
        fullPrompt = `${instructions}\n\n---\n\n## Task:\n${userPrompt}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary. Output only the finished work product.`;
      } else {
        fullPrompt = userPrompt;
      }

      send({ type: 'start', agent: agentName || 'custom' });
      const output = await runClaudeSync(fullPrompt);
      send({ type: 'done', output });
      send({ type: 'complete', output });
    } catch (err) {
      send({ type: 'error', error: err.message });
    }
    res.end();
  })();
});

// Global settings
app.get('/api/global/settings', (req, res) => {
  const content = readFileSafe(path.join(CLAUDE_DIR, 'settings.json'));
  try {
    res.json(content ? JSON.parse(content) : {});
  } catch {
    res.json({});
  }
});

// --- Setup / Health Endpoints ---

const { execSync } = require('child_process');

app.get('/api/setup/status', (req, res) => {
  // 1. pm2 status
  let pm2Status = 'unknown';
  try {
    const out = execSync('pm2 jlist 2>/dev/null', { encoding: 'utf-8', timeout: 5000 });
    const list = JSON.parse(out);
    const hub = list.find(p => p.name === 'claude-hub');
    pm2Status = hub ? hub.pm2_env.status : 'not_registered';
  } catch {
    pm2Status = 'not_installed';
  }

  // 2. LaunchAgent
  const launchAgentPath = path.join(os.homedir(), 'Library/LaunchAgents/io.boldteq.claude-hub.plist');
  const launchAgentInstalled = fs.existsSync(launchAgentPath);

  // 3. Agent count
  const agentDir = path.join(CLAUDE_DIR, 'agents');
  const agentCount = fs.existsSync(agentDir)
    ? fs.readdirSync(agentDir).filter(f => f.endsWith('.md')).length
    : 0;

  // 4. SDK location
  const sdkPath = path.join(__dirname, '..', 'sdk');
  const sdkExists = fs.existsSync(path.join(sdkPath, 'package.json'));

  res.json({ pm2Status, launchAgentInstalled, agentCount, sdkExists, port: process.env.PORT || 3847 });
});

app.get('/api/setup/projects', (req, res) => {
  const config = loadConfig();
  const results = [];

  for (const dir of config.projectDirs || []) {
    const resolved = dir.replace(/^~/, HOME);
    if (!fs.existsSync(resolved)) continue;
    try {
      const entries = fs.readdirSync(resolved, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) continue;
        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
        const projectPath = path.join(resolved, entry.name);
        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
        if (!hasClaudeDir && !hasClaudeMd && !hasPackageJson && !hasPubspec) continue;

        const hasSdk = fs.existsSync(path.join(projectPath, 'node_modules', '@boldteq', 'agents'));
        let hasPackageEntry = false;
        if (hasPackageJson) {
          try {
            const pkg = JSON.parse(fs.readFileSync(path.join(projectPath, 'package.json'), 'utf-8'));
            hasPackageEntry = !!(
              (pkg.dependencies && pkg.dependencies['@boldteq/agents']) ||
              (pkg.devDependencies && pkg.devDependencies['@boldteq/agents'])
            );
          } catch {}
        }

        results.push({
          name: entry.name,
          path: projectPath,
          hasSdk,
          hasPackageEntry,
        });
      }
    } catch {}
  }

  res.json(results);
});

app.post('/api/setup/install-sdk', (req, res) => {
  const { projectPath } = req.body;
  if (!projectPath || typeof projectPath !== 'string') {
    return res.status(400).json({ error: 'projectPath is required' });
  }

  // Validate path exists
  const resolvedProject = path.resolve(projectPath);
  if (!fs.existsSync(resolvedProject) || !fs.statSync(resolvedProject).isDirectory()) {
    return res.status(400).json({ error: 'Project path does not exist' });
  }

  // Validate it's within a known project dir
  const config = loadConfig();
  const allowedRoots = (config.projectDirs || []).map(d => path.resolve(d.replace(/^~/, HOME)));
  const isAllowed = allowedRoots.some(root => resolvedProject.startsWith(root));
  if (!isAllowed) {
    return res.status(403).json({ error: 'Path outside allowed project directories' });
  }

  // Read or create package.json
  const pkgPath = path.join(resolvedProject, 'package.json');
  let pkg = { name: path.basename(resolvedProject), version: '1.0.0', dependencies: {} };
  if (fs.existsSync(pkgPath)) {
    try {
      pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
    } catch {
      return res.status(500).json({ error: 'Could not parse project package.json' });
    }
  }

  // Calculate relative path from project to sdk
  const sdkAbsPath = path.resolve(path.join(__dirname, '..', 'sdk'));
  const relPath = path.relative(resolvedProject, sdkAbsPath);

  // Add dependency
  if (!pkg.dependencies) pkg.dependencies = {};
  pkg.dependencies['@boldteq/agents'] = `file:${relPath}`;
  fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2));

  // Run npm install
  try {
    execSync('npm install', { cwd: resolvedProject, timeout: 60000, stdio: 'pipe' });
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message || 'npm install failed' });
  }
});

// SPA fallback
app.get('*', (req, res) => {
  res.sendFile(path.join(staticPath, 'index.html'));
});

const PORT = process.env.PORT || 3847;
app.listen(PORT, () => {
  console.log('');
  console.log('  ╔══════════════════════════════════════╗');
  console.log('  ║         Claude Hub is running         ║');
  console.log(`  ║     http://localhost:${PORT}            ║`);
  console.log('  ╚══════════════════════════════════════╝');
  console.log('');
  console.log(`  Claude dir: ${CLAUDE_DIR}`);
  console.log(`  Config: ${CONFIG_PATH}`);
  console.log('');
});

