import { useState, useEffect, useMemo, useCallback } from 'react'
import { useParams, useNavigate, NavLink } from 'react-router-dom'
import {
  BookOpen, Copy, Check, ChevronRight, Hash, Terminal,
  Table2, List, AlignLeft,
} from 'lucide-react'

interface DocMeta {
  slug: string
  filename: string
  title: string
  description: string
}

// ─── Markdown Tokenizer ───────────────────────────────────────────────────────

type Token =
  | { type: 'h1' | 'h2' | 'h3' | 'h4'; id: string; text: string }
  | { type: 'hr' }
  | { type: 'code'; lang: string; text: string }
  | { type: 'table'; headers: string[]; rows: string[][] }
  | { type: 'ul'; items: string[]; depth: number }
  | { type: 'ol'; items: string[]; start: number }
  | { type: 'paragraph'; text: string }
  | { type: 'blank' }

function slugify(text: string): string {
  return text.toLowerCase().replace(/[^a-z0-9\s-]/g, '').trim().replace(/\s+/g, '-')
}

function tokenize(md: string): Token[] {
  const tokens: Token[] = []
  const lines = md.split('\n')
  let i = 0

  while (i < lines.length) {
    const line = lines[i]

    // Blank
    if (line.trim() === '') { i++; continue }

    // Headings
    const hm = line.match(/^(#{1,4})\s+(.+)$/)
    if (hm) {
      const level = hm[1].length
      const text = hm[2].replace(/\s+#+\s*$/, '') // strip trailing hashes
      const type = (['h1', 'h2', 'h3', 'h4'] as const)[level - 1]
      tokens.push({ type, id: slugify(text), text })
      i++; continue
    }

    // Horizontal rule
    if (line.match(/^[-*_]{3,}\s*$/)) {
      tokens.push({ type: 'hr' })
      i++; continue
    }

    // Fenced code block
    if (line.match(/^```/)) {
      const lang = line.slice(3).trim()
      const codeLines: string[] = []
      i++
      while (i < lines.length && !lines[i].match(/^```\s*$/)) {
        codeLines.push(lines[i])
        i++
      }
      i++ // skip closing ```
      tokens.push({ type: 'code', lang, text: codeLines.join('\n') })
      continue
    }

    // Table (must start with |)
    if (line.startsWith('|')) {
      const tableLines: string[] = []
      while (i < lines.length && lines[i].trimStart().startsWith('|')) {
        tableLines.push(lines[i])
        i++
      }
      if (tableLines.length >= 2) {
        const parseRow = (r: string) =>
          r.split('|').slice(1, -1).map(c => c.trim()).filter((_, idx, arr) => idx < arr.length)
        const headers = parseRow(tableLines[0])
        const rows: string[][] = []
        for (let j = 2; j < tableLines.length; j++) {
          rows.push(parseRow(tableLines[j]))
        }
        tokens.push({ type: 'table', headers, rows })
      }
      continue
    }

    // Unordered list
    if (line.match(/^(\s*)[-*+]\s/)) {
      const items: string[] = []
      const depth = line.match(/^(\s*)/)?.[1].length ?? 0
      while (i < lines.length && lines[i].match(/^(\s*)[-*+]\s/)) {
        items.push(lines[i].replace(/^(\s*)[-*+]\s/, ''))
        i++
      }
      tokens.push({ type: 'ul', items, depth })
      continue
    }

    // Ordered list
    if (line.match(/^\d+\.\s/)) {
      const items: string[] = []
      const start = parseInt(line.match(/^(\d+)/)?.[1] ?? '1', 10)
      while (i < lines.length && lines[i].match(/^\d+\.\s/)) {
        items.push(lines[i].replace(/^\d+\.\s/, ''))
        i++
      }
      tokens.push({ type: 'ol', items, start })
      continue
    }

    // Paragraph — collect until blank or block element
    const paraLines: string[] = []
    while (
      i < lines.length &&
      lines[i].trim() !== '' &&
      !lines[i].match(/^#{1,4}\s/) &&
      !lines[i].match(/^```/) &&
      !lines[i].trimStart().startsWith('|') &&
      !lines[i].match(/^(\s*)[-*+]\s/) &&
      !lines[i].match(/^\d+\.\s/) &&
      !lines[i].match(/^[-*_]{3,}\s*$/)
    ) {
      paraLines.push(lines[i])
      i++
    }
    if (paraLines.length > 0) {
      tokens.push({ type: 'paragraph', text: paraLines.join('\n') })
    }
  }

  return tokens
}

// ─── Inline Renderer ─────────────────────────────────────────────────────────

function InlineText({ text }: { text: string }) {
  const parts: React.ReactNode[] = []
  let i = 0
  let buf = ''
  let key = 0

  const flush = () => {
    if (buf) { parts.push(buf); buf = '' }
  }

  while (i < text.length) {
    // Bold **text**
    if (text[i] === '*' && text[i + 1] === '*') {
      const end = text.indexOf('**', i + 2)
      if (end !== -1) {
        flush()
        parts.push(<strong key={key++} className="font-semibold text-text">{text.slice(i + 2, end)}</strong>)
        i = end + 2; continue
      }
    }
    // Italic *text*
    if (text[i] === '*' && text[i + 1] !== '*') {
      const end = text.indexOf('*', i + 1)
      if (end !== -1) {
        flush()
        parts.push(<em key={key++} className="italic text-text-secondary">{text.slice(i + 1, end)}</em>)
        i = end + 1; continue
      }
    }
    // Inline code `code`
    if (text[i] === '`') {
      const end = text.indexOf('`', i + 1)
      if (end !== -1) {
        flush()
        parts.push(
          <code key={key++} className="font-mono text-accent bg-accent-muted px-1.5 py-0.5 rounded text-[12px] border border-accent/20">
            {text.slice(i + 1, end)}
          </code>
        )
        i = end + 1; continue
      }
    }
    // Link [text](url)
    if (text[i] === '[') {
      const cb = text.indexOf(']', i)
      if (cb !== -1 && text[cb + 1] === '(') {
        const cp = text.indexOf(')', cb + 2)
        if (cp !== -1) {
          flush()
          const linkText = text.slice(i + 1, cb)
          const url = text.slice(cb + 2, cp)
          const isExternal = url.startsWith('http')
          parts.push(
            <a key={key++} href={url} className="text-accent hover:text-accent-hover underline underline-offset-2"
              target={isExternal ? '_blank' : undefined} rel={isExternal ? 'noopener noreferrer' : undefined}>
              {linkText}
            </a>
          )
          i = cp + 1; continue
        }
      }
    }
    buf += text[i]
    i++
  }
  flush()
  return <>{parts}</>
}

// ─── Code Block ──────────────────────────────────────────────────────────────

function CodeBlock({ lang, text }: { lang: string; text: string }) {
  const [copied, setCopied] = useState(false)

  const copy = () => {
    navigator.clipboard.writeText(text)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <div className="my-4 rounded-xl border border-border overflow-hidden">
      <div className="flex items-center justify-between px-4 py-2 bg-surface-2 border-b border-border">
        <div className="flex items-center gap-2">
          <Terminal className="w-3.5 h-3.5 text-text-muted" />
          <span className="text-[11px] font-mono text-text-muted uppercase tracking-wider">
            {lang || 'text'}
          </span>
        </div>
        <button
          onClick={copy}
          className="flex items-center gap-1.5 text-[11px] text-text-muted hover:text-text transition-colors"
        >
          {copied ? <Check className="w-3.5 h-3.5 text-green" /> : <Copy className="w-3.5 h-3.5" />}
          {copied ? 'Copied' : 'Copy'}
        </button>
      </div>
      <pre className="p-4 overflow-x-auto bg-surface text-[13px] font-mono text-text-secondary leading-relaxed">
        <code>{text}</code>
      </pre>
    </div>
  )
}

// ─── Token Renderer ───────────────────────────────────────────────────────────

function RenderTokens({ tokens }: { tokens: Token[] }) {
  return (
    <>
      {tokens.map((token, idx) => {
        switch (token.type) {
          case 'h1':
            return (
              <h1 key={idx} id={token.id} className="text-2xl font-bold text-text mt-8 mb-4 pb-3 border-b border-border scroll-mt-6">
                <InlineText text={token.text} />
              </h1>
            )
          case 'h2':
            return (
              <h2 key={idx} id={token.id} className="text-xl font-semibold text-text mt-8 mb-3 flex items-center gap-2 scroll-mt-6">
                <span className="w-1 h-5 bg-accent rounded-full shrink-0" />
                <InlineText text={token.text} />
              </h2>
            )
          case 'h3':
            return (
              <h3 key={idx} id={token.id} className="text-base font-semibold text-text mt-6 mb-2 scroll-mt-6">
                <InlineText text={token.text} />
              </h3>
            )
          case 'h4':
            return (
              <h4 key={idx} id={token.id} className="text-sm font-semibold text-text-secondary mt-4 mb-1.5 scroll-mt-6">
                <InlineText text={token.text} />
              </h4>
            )
          case 'hr':
            return <hr key={idx} className="my-8 border-border" />
          case 'code':
            return <CodeBlock key={idx} lang={token.lang} text={token.text} />
          case 'table':
            return (
              <div key={idx} className="my-4 rounded-xl border border-border overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="bg-surface-2 border-b border-border">
