                            <InlineText text={h} />
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {token.rows.map((row, ri) => (
                        <tr key={ri} className={`border-b border-border last:border-0 ${ri % 2 === 1 ? 'bg-surface-2/40' : ''}`}>
                          {row.map((cell, ci) => (
                            <td key={ci} className="px-4 py-2.5 text-[13px] text-text-secondary">
                              <InlineText text={cell} />
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )
          case 'ul':
            return (
              <ul key={idx} className="my-3 space-y-1.5">
                {token.items.map((item, ii) => (
                  <li key={ii} className="flex items-start gap-2.5 text-[14px] text-text-secondary leading-relaxed">
                    <span className="mt-1.5 w-1.5 h-1.5 rounded-full bg-accent shrink-0" />
                    <span><InlineText text={item} /></span>
                  </li>
                ))}
