                  </li>
                ))}
              </ol>
            )
          case 'paragraph':
            return (
              <p key={idx} className="my-3 text-[14px] text-text-secondary leading-relaxed">
                <InlineText text={token.text} />
              </p>
            )
          default:
            return null
        }
      })}
    </>
  )
}

// ─── Table of Contents ────────────────────────────────────────────────────────

function TableOfContents({ tokens }: { tokens: Token[] }) {
  const headings = tokens.filter(
    (t): t is Extract<Token, { type: 'h2' | 'h3' }> =>
