  const tokens = useMemo(() => (content ? tokenize(content) : []), [content])

  const currentTitle = useMemo(() => {
    if (!slug) return 'Documentation'
    const label = DOC_LABELS[slug]
    if (label) return label.short
    return docs.find(d => d.slug === slug)?.title || 'Documentation'
  }, [slug, docs])

  return (
    <div className="flex h-screen overflow-hidden bg-bg">
      {/* ── Left: doc list ── */}
      <aside className="w-[240px] min-w-[240px] border-r border-border flex flex-col overflow-hidden">
        <div className="px-4 py-4 border-b border-border">
          <div className="flex items-center gap-2">
            <BookOpen className="w-4 h-4 text-accent" />
            <span className="text-[13px] font-semibold text-text">Documentation</span>
          </div>
          <p className="text-[11px] text-text-muted mt-1">Step-by-step guides</p>
        </div>
        <nav className="flex-1 overflow-y-auto py-2">
          {docsLoading ? (
            <div className="px-4 space-y-2 mt-2">
              {[...Array(8)].map((_, i) => (
                <div key={i} className="h-8 bg-surface-2 rounded-lg animate-pulse" />
              ))}
            </div>
          ) : docs.map(doc => {
            const label = DOC_LABELS[doc.slug]
            const isActive = slug === doc.slug
            return (
              <button
                key={doc.slug}
                onClick={() => navigate(`/docs/${doc.slug}`)}
                className={`w-full text-left px-4 py-2.5 text-[13px] flex items-center gap-2.5 transition-all ${
                  isActive
                    ? 'bg-accent-muted text-accent font-medium border-r-2 border-accent'
                    : 'text-text-secondary hover:text-text hover:bg-surface-2'
                }`}
              >
                <span className="text-[14px] shrink-0 w-5 text-center">
                  {label?.emoji || '📄'}
                </span>
                <span className="truncate">{label?.short || doc.title}</span>
                {isActive && <ChevronRight className="w-3 h-3 ml-auto shrink-0" />}
              </button>
            )
          })}
        </nav>
        <div className="px-4 py-3 border-t border-border">
          <p className="text-[10px] text-text-muted">
            {docs.length} guides · claude-hub/docs/
          </p>
        </div>
      </aside>

      {/* ── Main content ── */}
      <div className="flex-1 flex overflow-hidden">
        <main className="flex-1 overflow-y-auto">
          {/* Header bar */}
          <div className="sticky top-0 z-10 bg-bg/95 backdrop-blur border-b border-border px-8 py-3 flex items-center gap-2">
            <BookOpen className="w-4 h-4 text-accent" />
            <span className="text-[13px] text-text-muted">Docs</span>
            <ChevronRight className="w-3.5 h-3.5 text-text-muted" />
            <span className="text-[13px] font-medium text-text">{currentTitle}</span>
          </div>

          {/* Content */}
          <div className="max-w-3xl mx-auto px-8 py-8 pb-20">
            {loading ? (
              <div className="space-y-4 mt-4">
                <div className="h-8 bg-surface-2 rounded-xl w-2/3 animate-pulse" />
                <div className="h-4 bg-surface-2 rounded w-full animate-pulse" />
                <div className="h-4 bg-surface-2 rounded w-5/6 animate-pulse" />
                <div className="h-4 bg-surface-2 rounded w-4/5 animate-pulse" />
                <div className="h-32 bg-surface-2 rounded-xl w-full animate-pulse mt-6" />
              </div>
            ) : tokens.length > 0 ? (
              <RenderTokens tokens={tokens} />
            ) : !slug ? (
              <div className="text-center py-20">
                <BookOpen className="w-12 h-12 text-text-muted mx-auto mb-4" />
                <p className="text-text-secondary">Select a doc from the sidebar</p>
              </div>
            ) : null}
          </div>
        </main>

        {/* ── Right: table of contents ── */}
        {tokens.length > 0 && (
          <aside className="hidden xl:block w-[220px] min-w-[220px] border-l border-border overflow-y-auto">
            <div className="px-4 py-4">
              <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted mb-3 flex items-center gap-1.5">
                <Hash className="w-3 h-3" />
                On this page
              </p>
              <TableOfContents tokens={tokens} />
            </div>
          </aside>
        )}
      </div>
    </div>
  )
}

