import { useState, useEffect } from 'react'
import { Settings, Trash2, Save, FolderOpen, Info, FolderSearch } from 'lucide-react'
import { getConfig, updateProjectDirs } from '../lib/api'
import { useApi } from '../hooks/useApi'
import DirectoryPicker from '../components/DirectoryPicker'
import { toast } from '../components/Toast'

interface Props {
  onSave: () => void
}

export default function SettingsPage({ onSave }: Props) {
  const { data: config, loading } = useApi(getConfig)
  const [dirs, setDirs] = useState<string[]>([])
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)
  const [pickerOpen, setPickerOpen] = useState(false)

  useEffect(() => {
    if (config) {
      setDirs(config.projectDirs || [])
      setDirty(false)
    }
  }, [config])

  const handleAddFromPicker = (dirPath: string) => {
    const display = dirPath.replace(/^\/Users\/[^/]+/, '~')
    if (!dirs.includes(dirPath) && !dirs.includes(display)) {
      setDirs([...dirs, display])
      setDirty(true)
    }
  }

  const handleRemove = (dir: string) => {
    setDirs(prev => prev.filter(d => d !== dir))
    setDirty(true)
  }

  const handleSave = async () => {
    setSaving(true)
    try {
      await updateProjectDirs(dirs)
      setDirty(false)
      onSave()
      toast('success', 'Settings saved')
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to save settings')
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="p-8 flex items-center justify-center h-64">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  return (
    <div className="p-8 max-w-3xl">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
            <Settings className="w-6 h-6 text-text-secondary" />
            Settings
          </h1>
          <p className="text-text-secondary text-sm mt-1">
            Configure Claude Hub
          </p>
        </div>
        <button
          onClick={handleSave}
          disabled={!dirty || saving}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          <Save className="w-4 h-4" />
          {saving ? 'Saving...' : 'Save'}
        </button>
      </div>

      {/* Info */}
      <div className="bg-accent-muted border border-accent/20 rounded-xl p-4 mb-6 flex items-start gap-3">
        <Info className="w-5 h-5 text-accent shrink-0 mt-0.5" />
        <div className="text-sm text-accent-hover">
          <p className="font-medium mb-1">How project discovery works</p>
          <p className="text-text-secondary">
            Add parent directories below. Claude Hub scans each directory for subdirectories
            containing <code className="text-accent font-mono text-xs">.claude/</code>,{' '}
            <code className="text-accent font-mono text-xs">CLAUDE.md</code>, or{' '}
            <code className="text-accent font-mono text-xs">package.json</code>.
          </p>
        </div>
      </div>

      {/* Claude directory info */}
      <div className="bg-surface border border-border rounded-xl p-5 mb-6">
        <div className="flex items-center gap-3">
          <FolderOpen className="w-5 h-5 text-text-muted" />
          <div>
            <p className="text-sm font-medium">Claude Directory</p>
            <p className="text-xs text-text-muted font-mono">{config?.claudeDir}</p>
          </div>
          <span
            className={`ml-auto text-xs px-2 py-1 rounded-md ${
              config?.claudeDirExists
                ? 'bg-green-muted text-green'
                : 'bg-red-muted text-red'
            }`}
          >
            {config?.claudeDirExists ? 'Found' : 'Not found'}
          </span>
        </div>
      </div>

      {/* Project Directories */}
      <div className="bg-surface border border-border rounded-xl p-5">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-semibold">Project Directories</h2>
          <button
            onClick={() => setPickerOpen(true)}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
          >
            <FolderSearch className="w-4 h-4" />
            Browse & Add
          </button>
        </div>

        {/* List */}
        {dirs.length === 0 ? (
          <div className="py-8 text-center">
            <FolderOpen className="w-10 h-10 text-text-muted mx-auto mb-3" />
            <p className="text-text-secondary font-medium">No directories configured</p>
            <p className="text-text-muted text-sm mt-1">
              Click "Browse & Add" to select folders containing your projects
            </p>
          </div>
        ) : (
          <div className="space-y-2">
            {dirs.map((dir) => (
              <div
                key={dir}
                className="flex items-center justify-between bg-surface-2 rounded-lg px-4 py-3 group"
              >
                <div className="flex items-center gap-3 min-w-0">
                  <FolderOpen className="w-4 h-4 text-text-muted shrink-0" />
                  <span className="text-sm font-mono text-text-secondary truncate">{dir}</span>
                </div>
                <button
                  onClick={() => handleRemove(dir)}
                  className="p-1.5 rounded-md text-text-muted hover:text-red hover:bg-red-muted transition-colors opacity-0 group-hover:opacity-100"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Directory Picker Modal */}
      <DirectoryPicker
        open={pickerOpen}
        onClose={() => setPickerOpen(false)}
        onSelect={handleAddFromPicker}
        existingDirs={dirs}
      />
    </div>
  )
}

import { Link } from 'react-router-dom'
import {
  Bot,
  FolderOpen,
  Terminal,
  ShieldCheck,
  Settings,
} from 'lucide-react'
import type { Project } from '../types'
import { getUnifiedAgents } from '../lib/api'
import { useApi } from '../hooks/useApi'

interface Props {
  projects: Project[]
}

export default function Dashboard({ projects }: Props) {
  const { data: allAgents } = useApi(getUnifiedAgents)

  const totalAgents = allAgents?.length || 0
  const globalAgents = allAgents?.filter((a) => a.scope === 'global').length || 0
  const totalCommands = projects.reduce((sum, p) => sum + p.commands.length, 0)
  const totalRules = projects.reduce((sum, p) => sum + p.rules.length, 0)

  const stats = [
    { label: 'Projects', value: projects.length, icon: FolderOpen, color: 'text-accent', bg: 'bg-accent-muted', link: '/settings' },
    { label: 'Total Agents', value: totalAgents, sub: `${globalAgents} global`, icon: Bot, color: 'text-purple', bg: 'bg-purple-muted', link: '/agents' },
    { label: 'Commands', value: totalCommands, icon: Terminal, color: 'text-amber', bg: 'bg-amber-muted', link: '/commands' },
    { label: 'Rules', value: totalRules, icon: ShieldCheck, color: 'text-green', bg: 'bg-green-muted', link: '/rules' },
  ]

  return (
    <div className="p-8 max-w-6xl">
      <div className="mb-8">
        <h1 className="text-2xl font-semibold tracking-tight">Dashboard</h1>
        <p className="text-text-secondary text-sm mt-1">
          Central hub for all your Claude agents, commands, and configurations
        </p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-4 gap-4 mb-8">
        {stats.map((s) => (
          <Link
            key={s.label}
            to={s.link}
            className="bg-surface rounded-xl border border-border p-5 flex items-start justify-between hover:border-accent/30 transition-all group"
          >
            <div>
              <p className="text-text-muted text-xs font-medium uppercase tracking-wider">
                {s.label}
              </p>
              <p className="text-3xl font-semibold mt-1 tracking-tight">{s.value}</p>
              {'sub' in s && s.sub && (
                <p className="text-xs text-text-muted mt-0.5">{s.sub}</p>
              )}
            </div>
            <div className={`p-2.5 rounded-lg ${s.bg} ${s.color}`}>
              <s.icon className="w-5 h-5" />
            </div>
          </Link>
        ))}
      </div>

      {/* Projects Grid */}
      {projects.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <FolderOpen className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">No projects found</p>
          <p className="text-text-muted text-sm mt-1 mb-4">
            Add project directories to start managing your Claude configs
          </p>
          <Link
            to="/settings"
            className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
          >
            <Settings className="w-4 h-4" />
            Open Settings
          </Link>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-4">
          {projects.map((p) => (
            <Link
              key={p.id}
              to={`/projects/${p.id}`}
              className="group flex items-center gap-3 bg-surface rounded-xl border border-border px-5 py-4 hover:border-accent/30 transition-all"
            >
              <div className="p-2 rounded-lg bg-surface-2 shrink-0">
                <FolderOpen className="w-4 h-4 text-accent" />
              </div>
              <h3 className="font-semibold text-[15px] group-hover:text-accent-hover transition-colors truncate">
                {p.name}
              </h3>
            </Link>
          ))}
        </div>
      )}
    </div>
  )
}

  {allGreen && projectsAllGood && (
    <div className="mt-4 flex items-center gap-2.5 px-4 py-3 bg-green-muted border border-green/20 rounded-xl">
      <CheckCircle className="w-4 h-4 text-green shrink-0" />
      <p className="text-xs text-green font-medium">All systems operational — Claude Hub is running, all agents loaded, SDK installed in all projects.</p>
    </div>
  )}
</div>

{/* ── Section 1: System Health ── */}
<section>
  <div className="flex items-center justify-between mb-1">
    <SectionHeader icon={Cpu} title="System Health" subtitle="Live status of every component. Click Refresh to update." />
    <button onClick={() => { refetchStatus(); refetchProjects() }} className="flex items-center gap-1.5 text-xs text-text-muted hover:text-text transition-colors mb-5">
      <RefreshCw className="w-3.5 h-3.5" /> Refresh
    </button>
  </div>

  {statusLoading ? (
    <div className="grid grid-cols-2 gap-4">
      {Array.from({ length: 4 }).map((_, i) => (
        <div key={i} className="h-28 bg-surface border border-border rounded-xl animate-pulse" />
      ))}
    </div>
  ) : (
    <div className="grid grid-cols-2 gap-4">
