// How It Works — Full System Visual
// One page. No walls of text. Every flow shown visually.

const ACCENT = '#6366f1'
const GREEN = '#22c55e'
const AMBER = '#f59e0b'
const PURPLE = '#a78bfa'
const RED = '#ef4444'

// ─── Arrow component ──────────────────────────────────────────────────────────

function Arrow({ dir = 'right', label }: { dir?: 'right' | 'down'; label?: string }) {
  if (dir === 'down') {
    return (
      <div className="flex flex-col items-center gap-1 my-1">
        {label && <span className="text-[10px] text-text-muted">{label}</span>}
        <div className="flex flex-col items-center">
          <div className="w-px h-6 bg-border" />
          <div className="w-0 h-0 border-l-[5px] border-r-[5px] border-t-[7px] border-l-transparent border-r-transparent border-t-border" />
        </div>
      </div>
    )
  }
  return (
    <div className="flex items-center gap-1 mx-1">
      {label && <span className="text-[10px] text-text-muted whitespace-nowrap">{label}</span>}
      <div className="flex items-center">
        <div className="h-px w-6 bg-border" />
        <div className="w-0 h-0 border-t-[5px] border-b-[5px] border-l-[7px] border-t-transparent border-b-transparent border-l-border" />
      </div>
    </div>
  )
}

// ─── Box component ────────────────────────────────────────────────────────────

function Box({
  label, sub, color = ACCENT, icon, tag, wide, muted,
}: {
  label: string
  sub?: string
  color?: string
  icon?: string
  tag?: string
  wide?: boolean
  muted?: boolean
}) {
  return (
    <div
      className={`rounded-xl border px-4 py-3 flex flex-col gap-1 ${wide ? 'min-w-[160px]' : 'min-w-[120px]'} ${muted ? 'opacity-50' : ''}`}
      style={{ borderColor: color + '40', background: color + '12' }}
    >
      {tag && (
        <span className="text-[9px] font-bold uppercase tracking-widest mb-0.5" style={{ color }}>
          {tag}
        </span>
      )}
      <div className="flex items-center gap-1.5">
        {icon && <span className="text-base leading-none">{icon}</span>}
        <span className="text-[13px] font-semibold text-text leading-tight">{label}</span>
      </div>
      {sub && <p className="text-[11px] text-text-muted leading-snug">{sub}</p>}
    </div>
  )
}

// ─── Step badge ───────────────────────────────────────────────────────────────

function Step({ n, label, sub, color = ACCENT }: { n: number; label: string; sub?: string; color?: string }) {
  return (
    <div className="flex items-start gap-3">
      <div
        className="w-6 h-6 rounded-full flex items-center justify-center text-[11px] font-bold shrink-0 mt-0.5"
        style={{ background: color + '25', color }}
      >
        {n}
      </div>
      <div>
        <p className="text-[13px] font-medium text-text leading-tight">{label}</p>
        {sub && <p className="text-[11px] text-text-muted mt-0.5 leading-snug">{sub}</p>}
      </div>
    </div>
  )
}

// ─── Section wrapper ──────────────────────────────────────────────────────────

function Section({ title, subtitle, children }: { title: string; subtitle?: string; children: React.ReactNode }) {
  return (
    <section className="space-y-4">
      <div>
        <h2 className="text-base font-semibold text-text">{title}</h2>
        {subtitle && <p className="text-[12px] text-text-muted mt-0.5">{subtitle}</p>}
      </div>
      {children}
    </section>
  )
}

// ─── Card ─────────────────────────────────────────────────────────────────────

function Card({ children, className = '' }: { children: React.ReactNode; className?: string }) {
  return (
    <div className={`bg-surface border border-border rounded-2xl p-5 ${className}`}>
      {children}
    </div>
  )
}

// ─── Label pill ───────────────────────────────────────────────────────────────

function Pill({ label, color = ACCENT }: { label: string; color?: string }) {
  return (
    <span
      className="inline-flex items-center px-2.5 py-0.5 rounded-full text-[11px] font-medium border"
      style={{ color, borderColor: color + '40', background: color + '18' }}
    >
      {label}
    </span>
  )
}

// ─── File chip ────────────────────────────────────────────────────────────────

function FileChip({ path, color = ACCENT }: { path: string; color?: string }) {
  return (
    <code
      className="inline-block text-[11px] font-mono px-2 py-0.5 rounded border"
      style={{ color, borderColor: color + '30', background: color + '10' }}
    >
      {path}
    </code>
  )
}

// ─── Main page ────────────────────────────────────────────────────────────────

