      {/* ══════════════════════════════════════════════════════════════
          SECTION 2 — FULL SYSTEM MAP
      ══════════════════════════════════════════════════════════════ */}
      <Section
        title="Full System Map"
        subtitle="Everything on your Mac and how it connects"
      >
        <Card>
          {/* Top row: Projects */}
          <div className="mb-2">
            <p className="text-[10px] font-bold uppercase tracking-widest text-text-muted mb-3">Your Projects  (~/Desktop/Boldteq App/)</p>
            <div className="flex gap-2 flex-wrap">
              {['Pinzo', 'Rankora', 'QuizSnap', 'Size Chart', 'CROBOT', 'Store Locator'].map(p => (
