@import "tailwindcss";

@theme {
  --color-bg: #09090b;
  --color-surface: #18181b;
  --color-surface-2: #27272a;
  --color-surface-3: #303033;
  --color-border: #3f3f46;
  --color-border-subtle: #27272a;
  --color-text: #fafafa;
  --color-text-secondary: #a1a1aa;
  --color-text-muted: #71717a;
  --color-accent: #6366f1;
  --color-accent-hover: #818cf8;
  --color-accent-muted: rgba(99, 102, 241, 0.15);
  --color-green: #22c55e;
  --color-green-muted: rgba(34, 197, 94, 0.15);
  --color-amber: #f59e0b;
  --color-amber-muted: rgba(245, 158, 11, 0.15);
  --color-red: #ef4444;
  --color-red-muted: rgba(239, 68, 68, 0.15);
  --color-purple: #a78bfa;
  --color-purple-muted: rgba(167, 139, 250, 0.15);

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', 'SF Mono', 'Fira Code', monospace;
}

@layer base {
  body {
    @apply bg-bg text-text font-sans antialiased;
  }

  ::selection {
    @apply bg-accent/30;
  }

  ::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }
  ::-webkit-scrollbar-track {
    @apply bg-transparent;
  }
  ::-webkit-scrollbar-thumb {
    @apply bg-border rounded-full;
  }
  ::-webkit-scrollbar-thumb:hover {
    @apply bg-text-muted;
  }
}

